import 'package:flutter/material.dart';
import '../models/models.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

const weekDays=['Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'];
const muscleGroups=['Peito','Costas','Ombros','Bíceps','Tríceps','Quadríceps','Posterior','Glúteos','Panturrilhas','Abdômen','Outros'];
const defaultExercises=<List<String>>[
 ['Supino reto','Peito'],['Supino inclinado','Peito'],['Crucifixo máquina','Peito'],['Crossover','Peito'],['Puxada aberta','Costas'],['Remada baixa','Costas'],['Remada unilateral','Costas'],['Pulldown','Costas'],['Desenvolvimento','Ombros'],['Elevação lateral','Ombros'],['Elevação frontal','Ombros'],['Rosca direta','Bíceps'],['Rosca alternada','Bíceps'],['Rosca martelo','Bíceps'],['Tríceps corda','Tríceps'],['Tríceps testa','Tríceps'],['Tríceps francês','Tríceps'],['Agachamento','Quadríceps'],['Leg press 45','Quadríceps'],['Cadeira extensora','Quadríceps'],['Mesa flexora','Posterior'],['Stiff','Posterior'],['Flexora sentado','Posterior'],['Hip thrust','Glúteos'],['Abdução de quadril','Glúteos'],['Panturrilha em pé','Panturrilhas'],['Panturrilha sentado','Panturrilhas'],['Abdominal supra','Abdômen'],['Prancha','Abdômen'],['Elevação de pernas','Abdômen']
];

class GymScreen extends StatefulWidget{const GymScreen({super.key});@override State<GymScreen> createState()=>_GymScreenState();}
class _GymScreenState extends State<GymScreen>{
 List<WorkoutPlan> plans=[];List<List<String>> custom=[];
 @override void initState(){super.initState();load();}
 Future<void> load()async{plans=(await StorageService.read('workout_plans')).map(WorkoutPlan.fromJson).toList();custom=(await StorageService.read('exercise_library')).map((e)=>[(e['name']??'').toString(),(e['muscle']??'Outros').toString()]).toList();if(mounted)setState((){});}
 Future<void> save()=>StorageService.write('workout_plans',plans.map((e)=>e.toJson()).toList());
 List<List<String>> get library{final all=[...defaultExercises,...custom];final seen=<String>{};return all.where((e)=>e.isNotEmpty&&seen.add(e[0].toLowerCase())).toList();}
 Future<void> create([WorkoutPlan? old])async{final draft=await Navigator.push<WorkoutPlanDraft>(context,MaterialPageRoute(builder:(_)=>PlanEditor(old:old,library:library,newExercise:newExercise)));if(draft==null)return;final p=old??WorkoutPlan(id:DateTime.now().microsecondsSinceEpoch.toString(),name:draft.name,weekdays:[],dayExercises:{});p.name=draft.name;p.weekdays=draft.weekdays.toList()..sort();p.dayExercises=draft.dayExercises;if(old==null)plans.add(p);await save();if(mounted)setState((){});}
 Future<List<String>?> newExercise()async{final n=TextEditingController();String m='Outros';final r=await showDialog<List<String>>(context:context,builder:(c)=>AlertDialog(title:const Text('Novo exercício'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Nome')),DropdownButtonFormField<String>(initialValue:m,items:muscleGroups.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)m=v;})]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('CANCELAR')),FilledButton(onPressed:()=>n.text.trim().isEmpty?null:Navigator.pop(c,[n.text.trim(),m]),child:const Text('SALVAR'))]));n.dispose();if(r==null)return null;if(!library.any((x)=>x[0].toLowerCase()==r[0].toLowerCase())){custom.add(r);await StorageService.write('exercise_library',custom.map((x)=>{'name':x[0],'muscle':x[1]}).toList());}return r;}
 Future<void> removePlan(WorkoutPlan p)async{plans.removeWhere((x)=>x.id==p.id);await save();if(mounted)setState((){});}
 Future<void> start(WorkoutPlan p,int day)async{final ex=p.exercisesFor(day).map((e)=>Exercise(id:e.id,name:e.name,muscle:e.muscle,sets:e.sets,reps:e.reps)).toList();if(ex.isEmpty)return;await Navigator.push(context,MaterialPageRoute(builder:(_)=>WorkoutExecution(name:p.name,weekday:day,exercises:ex)));}
 @override Widget build(BuildContext context){final today=DateTime.now().weekday;final todays=plans.where((p)=>p.weekdays.contains(today)&&p.exercisesFor(today).isNotEmpty).toList();return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Academia',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:()=>create(),icon:const Icon(Icons.add),label:const Text('Criar'))]),const SizedBox(height:12),if(todays.isNotEmpty)_todayCard(todays,today),if(plans.isEmpty)const AppCard(child:Text('Nenhum treino criado.')),for(final p in plans)_planCard(p),const _History()]));}
 Widget _todayCard(List<WorkoutPlan> list,int day)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Treino de hoje',style:Theme.of(context).textTheme.titleLarge),for(final p in list)ListTile(contentPadding:EdgeInsets.zero,title:Text(p.name),subtitle:Text('${p.exercisesFor(day).length} exercícios • ${weekDays[day-1]}'),trailing:FilledButton(onPressed:()=>start(p,day),child:const Text('Iniciar')))]));
 Widget _planCard(WorkoutPlan p)=>AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(p.name,style:Theme.of(context).textTheme.titleLarge)),PopupMenuButton<String>(onSelected:(v){if(v=='edit')create(p);if(v=='delete')removePlan(p);},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir'))])]),for(final d in p.weekdays)ListTile(contentPadding:EdgeInsets.zero,title:Text(weekDays[d-1]),subtitle:Text(p.exercisesFor(d).map((e)=>'${e.name} (${e.sets}×${e.reps})').join(', ')),trailing:IconButton(onPressed:()=>start(p,d),icon:const Icon(Icons.play_arrow)))]));
}

class WorkoutPlanDraft{final String name;final Set<int> weekdays;final Map<String,List<Exercise>> dayExercises;WorkoutPlanDraft({required this.name,required this.weekdays,required this.dayExercises});}
class PlanEditor extends StatefulWidget{final WorkoutPlan? old;final List<List<String>> library;final Future<List<String>?> Function() newExercise;const PlanEditor({super.key,required this.old,required this.library,required this.newExercise});@override State<PlanEditor> createState()=>_PlanEditorState();}
class _PlanEditorState extends State<PlanEditor>{late TextEditingController name;final days=<int>{};final ex=<String,List<Exercise>>{};@override void initState(){super.initState();name=TextEditingController(text:widget.old?.name??'');if(widget.old!=null){days.addAll(widget.old!.weekdays);widget.old!.dayExercises.forEach((k,v){ex[k]=v.map((e)=>e.copy()).toList();});}}@override void dispose(){name.dispose();super.dispose();}Future<void> editDay(int d)async{final r=await Navigator.push<List<Exercise>>(context,MaterialPageRoute(builder:(_)=>DayEditor(day:d,initial:(ex['$d']??[]).map((e)=>e.copy()).toList(),library:widget.library,newExercise:widget.newExercise)));if(r!=null&&mounted)setState((){days.add(d);ex['$d']=r;});}void save(){final valid=days.where((d)=>(ex['$d']??[]).isNotEmpty).toSet();if(name.text.trim().isEmpty||valid.isEmpty)return;Navigator.pop(context,WorkoutPlanDraft(name:name.text.trim(),weekdays:valid,dayExercises:ex));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Configurar treino')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Nome do treino')),for(var i=0;i<7;i++)ListTile(title:Text(weekDays[i]),subtitle:Text('${ex['${i+1}']?.length??0} exercício(s)'),trailing:const Icon(Icons.chevron_right),onTap:()=>editDay(i+1)),FilledButton(onPressed:save,child:const Text('SALVAR TREINO'))]));}

class DayEditor extends StatefulWidget{final int day;final List<Exercise> initial;final List<List<String>> library;final Future<List<String>?> Function() newExercise;const DayEditor({super.key,required this.day,required this.initial,required this.library,required this.newExercise});@override State<DayEditor> createState()=>_DayEditorState();}
class _DayEditorState extends State<DayEditor>{late List<Exercise> list;@override void initState(){super.initState();list=widget.initial;}Future<void> add()async{final e=await showDialog<Exercise>(context:context,builder:(_)=>ExercisePicker(library:widget.library,newExercise:widget.newExercise));if(e!=null&&mounted)setState(()=>list.add(e));}Future<void> edit(int i)async{final e=await showDialog<Exercise>(context:context,builder:(_)=>ExerciseSettings(initial:list[i]));if(e!=null&&mounted)setState(()=>list[i]=e);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(weekDays[widget.day-1]),actions:[TextButton(onPressed:()=>Navigator.pop(context,list),child:const Text('SALVAR'))]),body:ListView(padding:const EdgeInsets.all(16),children:[for(var i=0;i<list.length;i++)ListTile(title:Text(list[i].name),subtitle:Text('${list[i].sets} séries × ${list[i].reps} reps'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>edit(i),icon:const Icon(Icons.tune)),IconButton(onPressed:()=>setState(()=>list.removeAt(i)),icon:const Icon(Icons.delete))])),OutlinedButton.icon(onPressed:add,icon:const Icon(Icons.add),label:const Text('ADICIONAR EXERCÍCIO'))]));}

class ExercisePicker extends StatefulWidget{final List<List<String>> library;final Future<List<String>?> Function() newExercise;const ExercisePicker({super.key,required this.library,required this.newExercise});@override State<ExercisePicker> createState()=>_ExercisePickerState();}
class _ExercisePickerState extends State<ExercisePicker>{String query='';String? selected;@override Widget build(BuildContext context){final list=widget.library.where((e)=>e[0].toLowerCase().contains(query.toLowerCase())).toList();return AlertDialog(title:const Text('Exercício'),content:SizedBox(height:400,width:450,child:Column(children:[TextField(onChanged:(v)=>setState(()=>query=v)),Expanded(child:ListView(children:list.map((e)=>ListTile(title:Text(e[0]),subtitle:Text(e[1]),selected:selected==e[0],onTap:()=>setState(()=>selected=e[0]))).toList()))])),actions:[TextButton(onPressed:()async{final e=await widget.newExercise();if(e!=null&&mounted)setState(()=>selected=e[0]);},child:const Text('NOVO')),TextButton(onPressed:()=>Navigator.pop(context),child:const Text('CANCELAR')),FilledButton(onPressed:(){if(selected==null)return;final e=widget.library.firstWhere((x)=>x[0]==selected);Navigator.pop(context,Exercise(id:DateTime.now().microsecondsSinceEpoch.toString(),name:e[0],muscle:e[1],sets:3,reps:10));},child:const Text('ADICIONAR'))]);}}
class ExerciseSettings extends StatefulWidget{final Exercise initial;const ExerciseSettings({super.key,required this.initial});@override State<ExerciseSettings> createState()=>_ExerciseSettingsState();}
class _ExerciseSettingsState extends State<ExerciseSettings>{late int sets;late int reps;@override void initState(){super.initState();sets=widget.initial.sets;reps=widget.initial.reps;}@override Widget build(BuildContext context)=>AlertDialog(title:Text(widget.initial.name),content:Column(mainAxisSize:MainAxisSize.min,children:[Text('Séries: $sets'),Slider(value:sets.toDouble(),min:1,max:12,divisions:11,onChanged:(v)=>setState(()=>sets=v.round())),Text('Repetições: $reps'),Slider(value:reps.toDouble(),min:1,max:30,divisions:29,onChanged:(v)=>setState(()=>reps=v.round()))]),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('CANCELAR')),FilledButton(onPressed:()=>Navigator.pop(context,Exercise(id:widget.initial.id,name:widget.initial.name,muscle:widget.initial.muscle,sets:sets,reps:reps)),child:const Text('SALVAR'))]);}

class WorkoutExecution extends StatefulWidget{final String name;final int weekday;final List<Exercise> exercises;const WorkoutExecution({super.key,required this.name,required this.weekday,required this.exercises});@override State<WorkoutExecution> createState()=>_WorkoutExecutionState();}
class _WorkoutExecutionState extends State<WorkoutExecution>{late List<List<TextEditingController>> controllers;late List<List<bool>> done;@override void initState(){super.initState();controllers=widget.exercises.map((e)=>List.generate(e.sets,(_)=>TextEditingController())).toList();done=widget.exercises.map((e)=>List<bool>.filled(e.sets,false)).toList();}@override void dispose(){for(final row in controllers){for(final c in row){c.dispose();}}super.dispose();}double? kg(int i,int s)=>double.tryParse(controllers[i][s].text.replaceAll(',','.').trim());Future<void> finish()async{for(var i=0;i<widget.exercises.length;i++){for(var s=0;s<widget.exercises[i].sets;s++){final v=kg(i,s);if(!done[i][s]||v==null||v<0){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Informe a carga e conclua todas as séries.')));return;}}}final completed=<Exercise>[];for(var i=0;i<widget.exercises.length;i++){final e=widget.exercises[i].copy();e.weights=List.generate(e.sets,(s)=>kg(i,s)!);e.done=[...done[i]];completed.add(e);}final h=await StorageService.read('workout_history');h.add(Workout(id:DateTime.now().microsecondsSinceEpoch.toString(),name:widget.name,date:DateTime.now().toIso8601String(),weekday:widget.weekday,exercises:completed).toJson());await StorageService.write('workout_history',h);if(mounted)Navigator.pop(context);}@override Widget build(BuildContext context){return Scaffold(appBar:AppBar(title:Text(widget.name)),body:ListView(padding:const EdgeInsets.all(16),children:[Text('Execução do treino',style:Theme.of(context).textTheme.headlineSmall),for(var i=0;i<widget.exercises.length;i++)_exerciseCard(i),FilledButton(onPressed:finish,child:const Text('FINALIZAR TREINO'))]));}Widget _exerciseCard(int i){return AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(widget.exercises[i].name,style:Theme.of(context).textTheme.titleLarge),Text(widget.exercises[i].muscle),for(var s=0;s<widget.exercises[i].sets;s++)Row(children:[SizedBox(width:60,child:Text('Série ${s+1}')),SizedBox(width:85,child:TextField(controller:controllers[i][s],keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(hintText:'kg'))),Expanded(child:Text('${widget.exercises[i].reps} reps')),Checkbox(value:done[i][s],onChanged:(v)=>setState(()=>done[i][s]=v==true))])]));}}
class _History extends StatefulWidget{const _History();@override State<_History> createState()=>_HistoryState();}class _HistoryState extends State<_History>{List<Workout> history=[];String? exercise;@override void initState(){super.initState();load();}Future<void> load()async{history=(await StorageService.read('workout_history')).map(Workout.fromJson).toList();if(mounted)setState((){});}@override Widget build(BuildContext context){if(history.isEmpty)return const SizedBox.shrink();final names=history.expand((w)=>w.exercises.map((e)=>e.name)).toSet().toList()..sort();exercise??=(names.isEmpty?null:names.first);return AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Histórico e evolução',style:Theme.of(context).textTheme.titleLarge),if(exercise!=null)DropdownButtonFormField<String>(initialValue:exercise,items:names.map((e)=>DropdownMenuItem(value:e,child:Text(e))).toList(),onChanged:(v)=>setState(()=>exercise=v)),for(final w in history.where((w)=>w.exercises.any((e)=>e.name==exercise)).take(10))_tile(w)]));}Widget _tile(Workout w){final e=w.exercises.firstWhere((e)=>e.name==exercise);final max=e.weights.fold<double>(0,(a,b)=>b>a?b:a);return ListTile(contentPadding:EdgeInsets.zero,title:Text('${max.toStringAsFixed(1)} kg'),subtitle:Text(w.date.substring(0,10)));}}
